// Extract the JSON payload from Sonnet's text block. Sonnet is asked
// for a single JSON object — strip any leading/trailing prose just in
// case the model wraps it.
const items = $input.all();
const out = [];
for (const item of items) {
  const blocks = item.json.content || [];
  const text = blocks.map(b => b.text || '').join('\n').trim();
  let parsed = null;
  try {
    const start = text.indexOf('{');
    const end   = text.lastIndexOf('}');
    if (start >= 0 && end > start) {
      parsed = JSON.parse(text.slice(start, end + 1));
    }
  } catch (e) {
    parsed = null;
  }
  const src = $('Split Rows').item.json;
  out.push({ json: {
    id: src.id,
    ...((parsed && typeof parsed === 'object') ? parsed : {}),
  }});
}
return out;
